\section{Preliminaries}\label{sect-preliminaries}
Let $C$ be a compact Riemann surface of genus $g \geq 2$, and $K$ denotes its canonical line bundle.
In this section, we recall the Bia\l ynicki-Birula stratification of the Hodge moduli space of $\lambda$-connections \cite{simpson-hodge-filtration, simpson-iterated}, following \cite{collier-wentworth, HH21}.
This Hitchin moduli space of Higgs bundles and the de Rham moduli space of flat connections are respectively the fibers $\lambda = 0$ and $\lambda = 1$ of the Hodge moduli space. 
Restricting the Bia\l ynicki-Birula stratification to these fibers then define the Bia\l ynicki-Birula stratification of the Hitchin moduli space and Simpson partial oper stratification of the de Rham moduli space.

Throughout this paper, we will consider rank-2 Higgs bundles and flat bundles with fixed determinants $\Lambda$.
Our convention is that, whenever we consider these as special cases of $\lambda$-connections, we let $\Lambda = \mathcal{O}_C$.
On the other hand, when we consider holomorphic bundles and Higgs bundles in and of themselves as in \Cref{subsec-BA-divisors}, \Cref{sect-degeneration-BA} and \Cref{subsec-moduli-bundles}, we can let $\Lambda$ be a fixed line bundle of degree $\deg(\Lambda) \in \{0, 1\}$.

\subsection{$\lambda$-connections and the Bia\l ynicki-Birula stratification}\label{subsubsec-natural-stratification}
\label{subsec-moduli-Higgs}
\paragraph{Moduli spaces}
Throughout our paper, a $\lambda$-connection is a triple $(\lambda, E, \nabla_\lambda)$, 
where $\lambda \in \C$, $E$ is a holomorphic rank-$2$ bundle with $\det(E) \cong \mathcal{O}_C$, 
and $\nabla_\lambda : E \rightarrow E \otimes K$ satisfies the twisted Leibniz rule 
\[ \nabla_\lambda(f s) = \lambda \; \partial f \otimes s + f \nabla_\lambda (s) \]
for local holomorphic functions $f$ and local sections $s$ of $E$, and induces a fixed $\lambda$-connection on $\det(E)$.
A $\lambda$-connection with $\lambda = 0$ is an $\SL_2(\C)$-Higgs bundle $(E, \phi)$ with $\phi \in H^0(\End_0(E) \otimes K)$, a traceless endomorphism of $E$ twisted by holomorphic differentials.
A $\lambda$-connection with $\lambda = 1$ is an $\SL_2(\C)$-holomorphic connection $(F, \nabla)$.

We denote by $\mathcal{M}_H(\Lambda)$ the moduli space of stable $\mathrm{SL}(2, \mathbb{C})$-Higgs bundles $(E, \phi)$ with $\det(E) \cong \Lambda$, 
and by $\mathcal{M}_{dR}$ the moduli space of irreducible $\mathrm{SL}(2, \mathbb{C})$-holomorphic connections $(E, \nabla)$ with $\det(E) \cong \mathcal{O}_C$.
Denote by $\mathcal{M}_{Hod}$ the moduli space of $\lambda$-connections $(\lambda, E, \nabla_\lambda)$ with $\det(E) \cong \mathcal{O}_C$.
The map $\underline{\lambda} : \mathcal{M}_{Hod} \rightarrow \C$ has fibers $\underline{\lambda}^{-1}(0) = \mathcal{M}_H(\mathcal{O}_C)$ and $\underline{\lambda}^{-1}(1) = \mathcal{M}_{dR}$.
Without loss of generality, we let $\deg(\Lambda) \in \{0, 1\}$ and write $\mathcal{M}_H \equiv \mathcal{M}_H(\Lambda)$ when the choice of $\Lambda$ does not matter. 

\paragraph{The $\C^\ast$-action and Hodge bundles}
The Hodge moduli space $\mathcal{M}_{Hod}$ admits a natural $\mathbb{C}^\ast$-action via 
\[
	t . [\lambda, E, \nabla_\lambda] \coloneqq [t\lambda, E, t\nabla_\lambda], \qquad t \in \C^\ast.
\]
On $\underline{\lambda}^{-1}(0) = \mathcal{M}_H(\mathcal{O}_C)$ and, in general, on $\mathcal{M}_H(\Lambda)$, 
the $\mathbb{C}^\ast$-action is $t.[E, \phi] = [E, t\phi]$.

Recall the Hitchin map 
\[ h: \mathcal{M}_H(\Lambda) \longrightarrow H^0(C, K^2), \qquad \qquad [E, \phi] \longmapsto \det(\phi),  \]
is a proper completely integrable system.
We say that a fixed point $\alpha \in \mathcal{M}_H^{\mathbb{C}^\ast}$, which is contained in the nilpotent cone $h^{-1}(0)$, is a Hodge bundle.
Given $x \in \mathcal{M}_{Hod}$, the limit $\underset{t \rightarrow}{\lim} \, t.x$ exists and is a Hodge bundle.
With $\mathcal{N}$ denoting the moduli space of rank-2 stable bundles with determinant $\Lambda$, one can write 
\begin{equation}\label{fixed-points}
	\mathcal{M}_H^{\C^\ast} = \mathcal{N} \sqcup \left( \sqcup_{d} N_d \right).
\end{equation}
Here, $\mathcal{N}$ parametrizes Higgs bundles of the form $(E, 0)$ with $E$ stable and of determinant $\Lambda$, and $N_d$ parametrizes Higgs bundles $(E_M, \phi_D)$ of the form 
\begin{align}\label{C*-fixed}
	&E_M = M \oplus M^{-1} \Lambda,
	& &\phi_{D} = \begin{pmatrix} 0 & 0 \\ s_D & 0 \end{pmatrix},
	& &s_D \in H^0(K M^{-2} \Lambda) \cong \mathcal{O}_C(D),
	& &D \in C^{(d)}.
\end{align}
Note that $d \equiv \deg(\Lambda)$ and that stability of $(E_M, \phi_D)$ requires $d < 2g-2$.


\paragraph{Upward flows and Bia\l ynicki-Birula stratification}
For a Hodge bundle $\alpha$, let
\[ \alpha^+ \coloneqq \left\{ x \in \mathcal{M}_{Hod} \, \big| \, \underset{t \rightarrow 0}{\lim} t.x = \alpha \right\} \]
--the upward flow of $\alpha$ in $\mathcal{M}_{Hod}$, and
\[ \alpha^+_\lambda \coloneqq \alpha^+  \cap \underline{\lambda}^{-1}(\lambda). \]
For a component $X \in \pi_0(\mathcal{M}_H^{\mathbb{C}^\ast})$, let
\[ X^+ \coloneqq \left\{ x \in \mathcal{M}_{Hod} \big| \underset{t \rightarrow 0}{\lim} t.x \in X \right\} \]
--the attractor of $X$ in $\mathcal{M}_{Hod}$, and
\[ X^+_\lambda \coloneqq X^+ \cap \underline{\lambda}^{-1}(\lambda). \]
We use the same notations $\alpha^+_0$ and $X^+_0$ respectively for the upward flow of $\alpha$ and attractor of $X$ in $\mathcal{M}_H(\Lambda)$ for general $\Lambda$. 
In particular, for $\alpha \in N_0$ which consists of $2^{2g}$ points, 
$\alpha^+_0$ and $\alpha^+_1$ correspond to a Hitchin section and space of holomorphic opers respectively.

\begin{theorem}[\cite{simpson-iterated, collier-wentworth}]\label{thm-CW}
	Let $\alpha$ be a stable Hodge bundle, contained in $X \in \pi_0(\mathcal{M}_H^{\mathbb{C}^\ast})$. 
	Then $\alpha^+_0 \subset \mathcal{M}_H$ and $\alpha^+_1 \subset \mathcal{M}_{dR}$ are holomorphic Lagrangian submanifolds, isomorphic as varieties with $\mathbb{C}^\ast$-action to the positive weighted subspace of $T_\alpha \mathcal{M}_H$.
	In particular, for $G = \mathrm{SL}(2, \mathbb{C})$, $\alpha^+_0$ and $\alpha^+_1$ are isomorphic to $\C^{3g-3}$. 
\end{theorem}

The decompositions  
\[ \mathcal{M}_{Hod} = \mathcal{N}^+ \sqcup \left( \sqcup_d N_d^+ \right),
\qquad \qquad \mathcal{M}_{H} = \mathcal{N}^+_0 \sqcup \left( \sqcup_d (N_d)^+_0 \right) \] 
define the Bia\l ynicki-Birula stratification on the Hodge moduli spaces and Hitchin moduli spaces, respectively.
The intersection of the former with $\mathcal{M}_{dR} \equiv \underline{\lambda}^{-1}(1)$ defines the Simpson partial oper stratification
\begin{equation}\label{BB-stratifications}
	\mathcal{M}_{dR} = \mathcal{N}^+_1 \sqcup \left( \sqcup_d (N_d)^+_1 \right).
\end{equation}

In all of these cases, the largest dimensional open stratum
\[ \mathcal{N}^+, \qquad \qquad \mathcal{N}^+_0, \qquad \qquad \mathcal{N}^+_1, \]
whose closures are the whole respective moduli spaces, parametrize $\lambda$-connections with stable underlying bundles.
The fibrations 
\[ \mathcal{N}^+_0 \longrightarrow \mathcal{N}, 
\qquad \qquad \mathcal{N}^+_1 \longrightarrow \mathcal{N} \]
are respectively the cotangent bundle $T^\ast \mathcal{N}$ and the twisted cotangent bundle of $\mathcal{N}$, i.e.
for $\alpha = E \in \mathcal{N}$,
\[ \alpha^+_0 = \{ (E, \phi) \in \mathcal{M}_H \}, 
\qquad \qquad \alpha^+_1 = \{ (E, \nabla) \in \mathcal{M}_{dR} \}. \]


\paragraph{Divisors from triples $(L \hookrightarrow E, \phi)$ and $(L \hookrightarrow E, \nabla)$}
Consider a rank-2 holomorphic bundle $E$ together with a line subbundle $L \hookrightarrow E$, i.e. an extension
\begin{equation} \label{bundle-extension}
	0 \rightarrow L \rightarrow E \rightarrow L^{-1}\Lambda \rightarrow 0.
\end{equation}
Given a Higgs field $\phi$ or a holomorphic connection $\nabla$ on $E$, consider the morphism
\begin{subequations}\label{eqn-section}
\begin{align}
	s_{L}( \phi): L \hookrightarrow E \overset{\phi}{\rightarrow} E \otimes K \rightarrow L^{-1} \Lambda K, \label{lower-left-component} \\
	s_{L}(\nabla): L \hookrightarrow E \overset{\nabla}{\rightarrow} E \otimes K \rightarrow L^{-1} K. \label{lower-left-dR-0}
\end{align}
\end{subequations}
One can check that the latter is also a $\mathcal{O}_C$-linear morphism,
and so these morphisms correspond to sections of $K L^{-2} \Lambda$ and $K L^{-2}$ respectively. 
Concretely, in local frames adapted to $L \hookrightarrow E$, one can write
\[ \phi = \begin{pmatrix}
 \ast & \ast \\ s_L(\phi) & \ast	
\end{pmatrix},
\qquad \qquad \qquad
\nabla = \partial + \begin{pmatrix}
	\ast & \ast \\ s_L(\nabla) & \ast
\end{pmatrix}.
\]
It is shown in \cite{DT23, Dinh24} that the extension class $[E]_L \in H^1(C, L^2 \Lambda^{-1})$ defined by \eqref{bundle-extension} pairs with these sections via Serre duality to
\[ \langle [E]_L, s_L(\phi) \rangle = 0, 
\qquad \qquad \langle [E]_L, s_L(\nabla) \rangle = \deg(L).  \]

Note that if $\det(\phi)$ is a quadratic differential with simple zeroes, i.e. the corresponding Hitchin fiber is smooth, (respectively, $\nabla$ is irreducible), 
then $s_L(\phi)$ (respectively, $s_L(\nabla)$) is not identically vanishing.
In this case, we denote by $D_L(\phi)$ and $D_L(\nabla)$ the corresponding zero divisors of these sections. 
The embedding of the subbundle $L$ into $E$ is unique up to scaling, which rescales $s_L$, so these zero divisors depend only on $L$.
In \Cref{subsec-BA-divisors} we also consider injections $L \overset{i}{\rightarrow} E$ that may vanish at some points, and then write $s_i$ and $D_i$.


\paragraph{Destabilizing subbundles.}
Let $E$ be strictly unstable, i.e. $E$ admits a unique destabilizing line subbundle $L_E \hookrightarrow E$ with $\deg(L_E^{-2}\Lambda) < 0$.
It follows that a Higgs bundle $(E, \phi)$ is stable if and only if $s_{L_E}(\phi) \neq 0$.

\begin{proposition}\label{prop-rank2-limits}
	Let $E$ be strictly unstable with destabilizing line subbundle $L_E \hookrightarrow E$.
	\begin{enumerate}[(i)]
		\item Let $[E, \phi] \in \mathcal{M}_H(\Lambda)$ and $\alpha = [E_M, \phi_D] \in N_d$ for some $d < 2g-2$.
		Then $[E, \phi] \in \alpha^+_0$ 
		if and only if $M$ is the unique destabilizing line subbundle of $E$ and 
		\[ D_{M}(\phi) = D. \]

		\item Let $[E, \nabla] \in \mathcal{M}_{dR}$ and $\alpha = [E_M, \phi_D] \in N_d$ for some $d < 2g-2$.
		Then $[E, \nabla] \in \alpha^+_1$ 
		if and only if $M$ is the unique destabilizing line subbundle of $E$ and 
		\[ D_{M}(\nabla) = D. \]
	\end{enumerate}
\end{proposition}

For rank $2$, Simpson proves that $(N_d)^+_1 \subset \overline{(N_{d+2})^+_1}$ for $d \leq 2g-6$ \cite[Theorem~7.6]{simpson-iterated}.
An explicit description of this closure relation and the relation to bubbling surgery is the subject of our paper. 

\paragraph{Very stable and wobbly Hodge bundle}
We say that a stable Hodge bundle $\alpha \in X \in \pi_0(\mathcal{M}_H^{\mathbb{C}^\ast})$ is \textit{very stable} if its upward flow $\alpha^+$ intersects the nilpotent cone $h^{-1}(0)$ exactly at $\alpha$; otherwise, we say that $\alpha$ is \textit{wobbly}.
These terminology and notion were first introduced by Drinfeld--Laumon \cite{Lau88} and Donagi--Pantev \cite{DP09} respectively for the case $X$ is the moduli space of stable bundles--a bundle is called \textit{wobbly} if it admits nonzero nilpotent Higgs fields and \textit{very stable} otherwise--and generalized to other components of Hodge bundles by Hausel--Hitchin \cite{HH21}. 

\begin{theorem} Let $\alpha$ be a stable Hodge bundle.
\begin{enumerate}[(i)]
		\item The Lagrangian leaf $\alpha^+_0$ is closed in $\mathcal{M}_H$ if and only if $\alpha$ is very stable \cite{PPe19, HH21}. 
		For $\alpha = [E_M, \phi_D] \in N_d$, this holds if and only if $D$ is reduced \cite{HH21}.
		\item The Lagrangian leaf $\alpha^+_1$ is closed in $\mathcal{M}_{dR}$ \cite{DS24}, but the leaves do not form a $C^1$ foliation \cite{Huang26}. 
\end{enumerate}
\end{theorem}
We remark that part (ii) answers the two parts of Simpson's question \cite[Question~7.4]{simpson-iterated}.
A similar description for $\alpha \in \mathcal{N}$ in terms of divisors of quadratic differentials is given in \cite{Dinh24wobbly}.



\subsection{Moduli spaces of rank-2 bundles}
\label{subsec-moduli-bundles}
Given a rank-2 holomorphic bundle $E$,
we say a subbundle $M$ of $E$ is a maximal subbundle of $E$ if $\deg(M) \geq \deg(L)$ for all other subbundles $L$ of $E$.
Clearly $E$ is stable if its Segre invariant 
\begin{equation*}
	s(E) \coloneqq \deg(\Lambda M^{-2}) 
	= \underset{L \hookrightarrow E}{\min} \; \deg(\Lambda L^{-2}),
\end{equation*} 
where $M$ is a maximal subbundle of $E$, is positive.
It follows by a theorem of Nagata \cite{Nagata} that $s(E) \leq g$.
As $s(E) \equiv \deg(\Lambda)$ mod $2$, we have 
\begin{equation}
	\max \: s(E) = 
	\begin{cases}
		g  & \text{for } g \equiv \deg(\Lambda) \pmod 2 \\
		g-1 & \text{for } g \equiv \deg(\Lambda)-1 \pmod 2 
	\end{cases}.
\end{equation}

The moduli space $\mathcal{N} \equiv \mathcal{N}_\Lambda$ of stable bundles with fixed determinant $\Lambda$ can be decomposed into 
\[ \mathcal{N} = \underset{s}{\sqcup} \, \mathcal{N}_s, 
\qquad \qquad \qquad 1 \leq s \leq g, \quad s \equiv \deg(\Lambda), \]
where $\mathcal{N}_s$ is the open Segre stratum defined by 
$\mathcal{N}_s = \{ [E] \in \mathcal{N} \mid s(E) = s \}$.
Then $\mathcal{N}_s$ is an irreducible algebraic variety of dimension $2g + s -2$.
These define a nested stratification called Segre stratification \cite{Lange-Narasimhan}.

It is known that if $s(E) = g$, then the set of its maximal subbundles is of dimension $1$ \cite{Lange-Narasimhan}.
On the other hand, a generic bundle $E$ with $s(E) = g-1$ only has a finite number of maximal subbundles,
and a generic bundle $E$ with $s(E) < g-1$ has only one maximal subbundle.
If however $E$ is strictly unstable, i.e. $s(E) < 0$,
then $E$ has a unique maximal subbundle $L_E$.
Regardless of the value of $s(E)$, 
if $M$ is a maximal subbundle of $E$ then its embedding into $E$ is unique up to a scaling, i.e. $h^0(M^{-1} E) = 1$.

We note that the Segre invariants also label the components of Hodge bundles with underlying unstable bundles. 
The Segre invariants therefore induce a finer stratification on $\mathcal{M}_H$ and $\mathcal{M}_{dR}$ by respectively refining the open stratum $\mathcal{N}^+_0$ and $\mathcal{N}^+_1$.
{%
