\section{Equations of the negative-spin sector}


In the same phantom gauge, the variables~\eqref{eq:negative-variables} satisfy
\begin{equation}
\begin{split} \label{eq:negative-np4}
 &\left(\mathcal L_2^\dagger-\frac{3F_0}{g}\right)\psi_{-2} +\Delta\left(\mathcal D_{-1}^\dagger+\frac3g\right)\psi_{-1} =2k_-F_+ \,,\\
 &\left(\mathcal D_0-\frac3g\right)\psi_{-2} -\left(\mathcal L_{-1}+\frac{3F_0}{g}\right)\psi_{-1} =2s_-F_- \,,\\
 &\Delta\left(\mathcal D_{-1}^\dagger+\frac3g\right)s_-  +\left(\mathcal L_{-1}+\frac{3F_0}{g}\right)k_-  =\frac{f\psi_{-2}}{g^2} \,,\\
 &\left(\mathcal D_0-\frac3g\right)k_- -\left(\mathcal L_2^\dagger-\frac{3F_0}{g}\right)s_-  =\frac{2f\psi_{-1}}{g^2} \,.
\end{split}
\end{equation}
Here $F_0,F_\pm,f,g$ retain their original definitions.


\section{Construction of the transformation matrix $X$} \label{app:algebraic-checks}

Since the two spin sectors differ only by the replacement $(\omega,m)\mapsto(-\omega,-m)$, it suffices to carry out the analysis for $\varsigma=+1$. We therefore suppress the $(+)$ superscripts and write $b=b^{(+)}$, $c=c^{(+)}$, $B=B^{(+)}$, $C=C^{(+)}$, $R_j=R_j^{(+)}$, and $\Theta_j=\Theta_j^{(+)}$ for $j=0,1$. The $\varsigma=-1$ results then follow by the same replacement, while $X$ and the coefficients $h_r,h_\theta$ remain unchanged.

\subsection{Mode matching and construction of X}

Substituting~\eqref{eq:separatedC} into~\eqref{eq:transformedcoupling} gives the equivalent matching condition
\begin{equation}  \label{eq:matrix-matching}
 (\det X)(cI-B)=XCX^\dagger \,.
\end{equation}
The combination $cI-B$ is linear in the two mode parameters $\omega,m$, so we write
\begin{equation}
 cI-B=\mathcal M_0+\omega\mathcal M_\omega+\Xi m\,\mathcal M_m \,.
\end{equation}
Here $\mathcal M_0$ is independent of $\omega$ and $m$, while $\mathcal M_\omega$ and $\mathcal M_m$ multiply $\omega$ and $\Xi m$, respectively. Since $X$ has no mode dependence and the target coefficients in \eqref{eq:alg-separated-coefficients} are linear in the same parameters, Eq.~\eqref{eq:matrix-matching} can be matched separately at orders $1$, $\omega$, and $\Xi m$.


Writing the two $\omega,m$-dependent equations in the Pauli basis singles out the angular and radial blocks
\begin{equation}
\begin{aligned}
 \mathcal A_\theta &=\ii Ma\cos\theta\,I-aQT\sin\theta\,\sigma_2 \,,\\
 \mathcal R_r &=\nu\sigma_3+\ii Q\sqrt{\Delta}\,\sigma_1 \,,
\end{aligned}
\end{equation}
where $\nu=Mr-Q^2$. They lie in the complementary subspaces $\{I,\sigma_2\}$ and $\{\sigma_1,\sigma_3\}$, respectively. We first construct the numerator matrix $N$ of $X$, before restoring the row factors $f^{-1},g^{-1}$ and the overall normalization. A simple separated ansatz is
\begin{equation}
 N=p(r)\mathcal A_\theta+q(\theta)\mathcal R_r \,.
\end{equation}
Substitution into the $\omega$- and $m$-coefficient equations gives,
up to the scalar freedom in~\eqref{eq:freedom},
\begin{equation}
\begin{aligned}
 p(r)&=A_r=r^2-\eta a^2,\\
 q(\theta)&=-D_\theta=-a^2(\cos^2\theta+\eta),
\end{aligned}
\end{equation}
provided
\begin{equation}  \label{eq:construction-eta}
 M^2\eta=Q^2(1+\eta)\left(1\pm\frac{a^2\eta}{L^2}\right)  \,,
\end{equation}
where the upper sign is for AdS and the lower sign for dS. We take $\kappa>0$ and the positive root $\eta$ given in~\eqref{eq:alg-parameters}, with the same sign replacement in dS. Hence
\begin{equation}
 N=A_r\mathcal A_\theta-D_\theta\mathcal R_r \,.
\end{equation}


\subsection{The transformation matrix $X$}

Equation~\eqref{eq:construction-eta} gives
\begin{equation}
\begin{split}
 \nu^2-Q^2\Delta 
 &=\frac{Q^2}{\eta}A_r\left(1\mp\frac{\eta r^2}{L^2}\right) \,,\\
 a^2(M^2\cos^2\theta+Q^2T^2\sin^2\theta)
   &=\frac{Q^2}{\eta}D_\theta
      \left(1\pm\frac{\eta a^2\cos^2\theta}{L^2}\right) \,.
\end{split}
\label{eq:alg-factorizations}
\end{equation}
The upper signs again refer to AdS and the lower signs to dS; correspondingly, $\kappa=Q^2\eta^{-1}(1\mp a^2\eta^2/L^2)$. These are $-\det\mathcal R_r$ and $-\det\mathcal A_\theta$, respectively. Hence
\begin{equation}
\begin{aligned}
\det N
 &=A_r^2\det\mathcal A_\theta+D_\theta^2\det\mathcal R_r\\
 &=-\kappa A_rD_\theta\Sigma \,.
\end{aligned}
\end{equation}
Multiplying the first and second rows by $f^{-1}$ and $g^{-1}$
restores the denominators of the original coupling matrix. The
constant-determinant representative is therefore
\begin{equation} \label{eq:construction-compact-X}
 X=\frac1{\kappa Q\sqrt{A_rD_\theta}} \operatorname{diag}(f^{-1},g^{-1})N.
\end{equation}
Expanding $X$ in terms of the Pauli matrices recovers~\eqref{eq:alg-frame}.


Furthermore, the differentiation of~\eqref{eq:construction-compact-X} gives
\begin{equation} 
 X^{-1}(\Dop X-AX)=(h_r+h_\theta)\sigma_2 \,.
\end{equation}
Writing $h=h_r+h_\theta$, we also have
\begin{equation}  \label{eq:construction-detX}
 \det X=-\frac1{\kappa Q^2}\,,\qquad  \Dop (\det X)=0\,,
\end{equation}
and hence
\begin{equation}
\begin{split}
 \Dop( (\det X) X^{-1})&=-(\det X) X^{-1}A- h\sigma_2(\det X)X^{-1},\\
 \bar\Dop(X^\dagger)&=X^\dagger A+h\sigma_2X^\dagger.
\end{split}
\end{equation}
These identities give the differential operators in~\eqref{eq:alg-chiral}. For either sector, $\tr B^{(\varsigma)}=0$ and real nonzero $\det X$ imply $(\det X)^{-1}X^\dagger(c^{(\varsigma)}I+B^{(\varsigma)})X =\adj C^{(\varsigma)}=2R_0^{(\varsigma)}I-C^{(\varsigma)}$.
\section{Invertibility of $X$ in the black hole exterior} \label{app:invertibility}
From~\eqref{eq:construction-compact-X} and \eqref{eq:construction-detX}, smooth invertibility reduces to showing that $\kappa$, $A_r$, $D_\theta$, and $\Sigma=fg$ do not vanish in the physical regions. Since $\eta>0$, we have $D_\theta>0$, while $\Sigma>0$ follows directly from the background geometry.



For KN--AdS, the explicit form of $\Delta$, together with $\Delta(r_+)=0$ and $\Delta'(r_+)>0$, implies
\begin{equation}
 M>|Q|\left(1+\frac{|a|}{L}\right) \,.
\end{equation}
It follows that $\kappa>0$, $\eta>0$, and $|a|\eta/L<1$. Evaluating~\eqref{eq:alg-factorizations} at $r=r_+$ gives
\begin{equation}  \label{eq:ads-horizon-factorization}
 (Mr_+-Q^2)^2 =\frac{Q^2}{\eta}  (r_+^2-\eta a^2)  \left(1-\frac{\eta r_+^2}{L^2}\right) \,.
\end{equation}
Suppose that $r_+^2\leq\eta a^2$. Then $1-\frac{\eta r_+^2}{L^2}\geq 1-\frac{\eta^2a^2}{L^2}>0$. The right-hand side of~\eqref{eq:ads-horizon-factorization} is therefore nonpositive, whereas the left-hand side is nonnegative. Hence both sides must vanish, forcing $r_+^2=\eta a^2$ and $Mr_+=Q^2$. Differentiating the first identity in~\eqref{eq:alg-factorizations} at $A_r=\nu=0$ gives $\Delta'(r_+)=-2r_+(\eta^{-1}-r_+^2/L^2)<0$, contrary to the simple outer-horizon condition $\Delta'(r_+)>0$. Hence $r_+^2>\eta a^2$, and therefore $A_r>0$ throughout $r>r_+$.



For KN--dS, the definitions give $\kappa>0$ and $\eta>0$. At the
event horizon $r=r_b$, we have similarly
\begin{equation}
 (Mr_b-Q^2)^2
 =\frac{Q^2}{\eta}
  (r_b^2-\eta a^2)
  \left(1+\frac{\eta r_b^2}{L^2}\right).
\end{equation}
The last factor is positive, so $r_b^2\geq\eta a^2$. Equality would
again imply $\Delta'(r_b)<0$, contradicting
$\Delta'(r_b)>0$. Thus $A_r>0$ throughout $r_b<r<r_c$.

Consequently, all factors in~\eqref{eq:construction-compact-X} are
smooth and nonzero in the exterior regions. Together
with
\begin{equation}
 \det X=-\frac{1}{\kappa Q^2},
\end{equation}
this proves that $X$ and the field transformation~\eqref{eq:change}
are smoothly invertible in both spin sectors.


\section{Axis and horizon conditions} \label{app:physical-boundaries}


The four fields in each sector have spin weights
$(2\varsigma,\varsigma,\varsigma,2\varsigma)$. Near the north and south axes, smooth tetrads are obtained by $m^\mu\mapsto e^{\ii\phi}m^\mu$ and $m^\mu\mapsto e^{-\ii\phi}m^\mu$, respectively. Thus, for a spin-$s$ mode proportional to $e^{\ii m\phi}$, smoothness requires $t^{|m+s|}A_N(t^2)$ and $t^{|m-s|}A_S(t^2)$ at the north and south axes, where $A_N$ and $A_S$ are smooth functions.

Write
\begin{equation}
\begin{split} 
 X&=\mathcal P+\sqrt\Delta\,\mathcal B \,,\\
 \mathcal B&=-\frac{\ii D_\theta}{\kappa\sqrt{A_rD_\theta}}
 \operatorname{diag}(f^{-1},g^{-1})\sigma_1 \,,
\end{split}
\end{equation}
where $\mathcal P$ is independent of $\sqrt\Delta$. Since $\adj(X^\dagger)=-\mathcal P+\sqrt\Delta\,\mathcal B$, the inverse transformation gives
\begin{equation}
\begin{aligned}
 Y_s:=y_++y_- &=\frac{(\sqrt\Delta\,\mathcal B u_1
          +\ii\mathcal P\sigma_2u_2)\chi}{\det X} \,, \\
 Y_d:=y_+-y_- &=\frac{(\mathcal P u_1
          +\ii\sqrt\Delta\,\mathcal B\sigma_2u_2)\chi}{\det X} \,.
\end{aligned}
\label{eq:boundary-exact-inverse}
\end{equation}
Here the factor $(A_rD_\theta)^{-1/2}$ is smooth and nonzero at the axes and horizons. Equation~\eqref{eq:chiralvars} determines the radiative NP variables from $Y_s$ and $Y_d$. After the powers of $t$ in~\eqref{eq:physical-axis-domain} are factored out, the remaining coefficient matrix is nonsingular because $\det X\neq0$. Hence a singular angular branch still produces a singular radiative NP variable; it cannot become regular through cancellation between components. We therefore keep the regular branch and exclude the singular one.


For a simple horizon, define
\begin{equation}
 r_*'=\frac{r^2+a^2}{\Delta},
 \qquad
 \Phi_*'=\frac{a\Xi}{\Delta}.
\end{equation}
At a future event horizon, the ingoing coordinates $v=t+r_*$ and $\phi_{\rm in}=\phi+\Phi_*$ give the factor $H^{-1}$. The tetrad $(\Delta\ell,\Delta^{-1}n,m,\bar m)$ is smooth there, so the following combinations of radiative variables must also be smooth:
\begin{equation}
\begin{aligned}
&H^{-1}(\Delta^2\psi_2,\Delta\psi_1,\Delta^2k,\Delta s),\\
&H^{-1}(\Delta^{-2}\psi_{-2},\Delta^{-1}\psi_{-1},
        \Delta^{-2}k_-,\Delta^{-1}s_-).
\end{aligned}
\end{equation}
At a future cosmological horizon, the outgoing coordinates $u=t-r_*$ and $\phi_{\rm out}=\phi-\Phi_*$ give the factor $H$, and the original tetrad is smooth.

Substituting~\eqref{eq:boundary-exact-inverse} into~\eqref{eq:chiralvars} and including the horizon factors above gives~\eqref{eq:physical-horizon-data}. After the powers of $H$ and $\Delta$ are removed, the remaining transformation has a nonsingular horizon limit: at $\Delta=0$, $\mathcal P=X$ and $\det\mathcal P=\det X\neq0$. Thus~\eqref{eq:physical-horizon-data} is precisely the condition that the radiative variables are smooth at the horizon in the regular tetrad. The same even--odd argument applies where an axis meets a horizon.


\section{Asymptotically flat limit} \label{app:flat-equivalence}
Let $M,a,Q$ be fixed, with $M^2>a^2+Q^2$ and $aQ\ne0$. As $L\to\infty$, the parameters satisfy $\kappa\to M^2-Q^2$ and $\eta\to Q^2/(M^2-Q^2)$. Taking this limit in~\eqref{eq:alg-frame}, we find the following relation to Hintz's matrix integrating factor $X_H$~\cite[Eq.~(5)]{Hintz2026}:
\begin{equation}
\begin{split} 
 X_H=&-QX\frac{\nu I+Q\sqrt{\Delta}\,\sigma_2}{\sqrt{A_r}}\\
 &\quad\times
 \frac{Qa\sin\theta\,I+\ii Ma\cos\theta\,\sigma_2}{\sqrt{D_\theta}} \,.
\end{split}
\end{equation}
The two factors to the right of $X$ depend only on $r$ and $\theta$, respectively, and are smooth and invertible throughout the subextremal KN exterior $r>r_+$. Thus, in the asymptotically flat limit, $X$ and Hintz's integrating factor are equivalent under the frame freedom~\eqref{eq:freedom}.

