\title{
Local wave-packet spectroscopy of the Drude weight in Tomonaga-Luttinger liquids
}

\author{Takayuki Yokoyama}
\email[]{author@example.org}
\affiliation{Quantum Matter Program, Graduate School of Advanced Science and Engineering, Hiroshima University,
Higashihiroshima, Hiroshima 739-8530, Japan}

\author{Yasuhiro Tada}
