\begin{observation}
\label{obs:hat_min_degree}
{For a simple connected graph $G$, $\mu(G) \leq \delta(G)$.}
\end{observation}

{Observation~\ref{obs:hat_min_degree} gives the first degree-based upper bound for simple graphs. The parameters $\lambda(G)$ and $\kappa(G)$ are often more informative than $\delta(G)$, and Whitney's inequalities~\cite{whitney} give
\[
    \kappa(G) \leq \lambda(G) \leq \delta(G).
\]
It is therefore natural to ask whether $\mu(G)$ can be bounded directly in terms of edge or vertex connectivity. Our first connectivity bound answers this for edge connectivity; in fact, it holds for loopless multigraphs.}

\begin{theorem}
\label{thm:edge_connectivity}
{For every connected multigraph $G$, $\mu(G) \leq \lambda(G)$.}
\end{theorem}
{We present the proof of \cref{thm:edge_connectivity} in \cref{sec:edge_connectivity}.}


We also give an upper bound for $\mu(G)$ in terms of vertex connectivity, $\kappa(G)$, for simple graphs.
\begin{theorem}
\label{thm:vertex_connectivity}
{For every simple connected graph $G$ with $|V(G)|\geq 4$, 
\[
    \mu(G) \leq 2^{\kappa(G)-1}+ \binom{\kappa(G)}{2}.
\]}
\end{theorem}
We note that when $G$ is disconnected and has a perfect matching, $\mu(G)=1$. Also, when $G$ is disconnected and has no perfect matching, $\mu(G)=0$. We present the proof for \cref{thm:vertex_connectivity} in \cref{sec:vertex_connectivity}.

{Finally, we revisit the smallest non-trivial cases. Cervera-Lierta et al.~\cite{CerveraLierta2022designofquantum} used SAT solvers to show that graphs on six and eight vertices have maximum dimension at most $2$ and $3$, respectively, in a more general setting allowing multi-edges. We give a purely combinatorial proof for simple graphs.}
\begin{theorem}
\label{thm:six_eight_vertices}
{For a simple graph, if $|V(G)|= 6$ then $\mu(G) \leq 2$ and if $|V(G)|= 8$ then $\mu(G) \leq 3$.}
\end{theorem}
 We present the proof of \cref{thm:six_eight_vertices} in \cref{sec:six_vertices}. 

{Theorem~\ref{thm:edge_connectivity} is tight for $K_4$: its edge connectivity is $3$, and its matching index is also $3$. Theorem~\ref{thm:vertex_connectivity} is tight for $\kappa(G)=1$, for instance for paths with a perfect matching. For $\kappa(G)=2$, stronger results are already known~\cite{CG3}; for higher connectivity, the optimal dependence on $\kappa(G)$ remains open, and in particular it is not known whether a polynomial bound in $\kappa(G)$ should hold. Indeed, any example on more than four vertices with matching index greater than $2$ would be a breakthrough, both as a counterexample to the Krenn--Gu conjecture and as a new route to high-dimensional GHZ-state generation.}

\section{Preliminaries}
\label{sec:prelim}
Let $G_c^w$ be a GHZ graph. We call a colour class $i$ of the colouring $c$ \emph{redundant} if it does not contain any monochromatic perfect matching of $G_c^w$. Suppose we remove all the edges of such a redundant colour class $i$ to form a new graph ${G'}_c^w$. Observe that any feasible vertex colouring of the new graph ${G'}_c^w$ has the same weight in ${G}_c^w$ and ${G'}_c^w$. Therefore, an edge-coloured edge-weighted graph remains a GHZ graph, even after removing all its edges from a redundant colour class. Moreover, the number of monochromatic vertex colourings of weight $1$ remains the same. Therefore, such a removal does not affect the dimension of the edge-coloured edge-weighted graph. The reader may note that a redundant colour class may have non-redundant edges.

{For $S\subseteq V(G)$, let $G[S]$ denote the subgraph induced by $S$. We write $\mathbb{N}$ and $\mathbb{C}$ for the natural and complex numbers, respectively. The cardinality of a set $\mathcal{S}$ is denoted by $|\mathcal{S}|$. For a positive integer $r$, let $[r]=\{1,2,\ldots,r\}$.}

For $S\subseteq V(G)$, we define $\mathbf{i}_S$ to be the monochromatic inherited vertex colouring using colour $i$ over the induced subgraph $G_c^w[S]$. Its weight is denoted by $w(\mathbf{i}_S)$. We emphasize that this weight is with respect to the induced subgraph $G_c^w[S]$. {We now prove factorisation observations that are used throughout the proofs. These factorisations hold for graphs of any order.}

\begin{observation}
\label{colour_split_lemma}
{Let $vc$ be an inherited vertex colouring using the colours $[r]$, and let
$V_i=\{v\in V(G): vc(v)=i\}$
for each $i\in [r]$. Then
\[
    w(vc)=\prod_{i=1}^{r}w(\mathbf{i}_{V_i}).
\]}
\end{observation}
\begin{proof}
{A perfect matching inducing $vc$ is exactly the disjoint union, over the colours $i$ used by $vc$, of a monochromatic perfect matching of colour $i$ in $G_c^w[V_i]$. Conversely, any such collection gives a perfect matching inducing $vc$. Summing products of edge weights over these independent choices gives the claimed product.}
\end{proof}

Let $G_c^w[\mathbf{i},S]$ denote the subgraph of $G_c^w[S]$ formed by all edges of $G_c^w[S]$ from colour class $i$.
\begin{observation}
\label{partition_split_lemma}
{For $S \subseteq V(G)$, let the connected components of $G_c^w[\mathbf{i},S]$ have vertex sets $S_1,\ldots,S_r$. Then
\[
    w(\mathbf{i}_S)=\prod_{j=1}^{r}w(\mathbf{i}_{S_j}).
\]}
\end{observation}
\begin{proof}
{A colour-$i$ perfect matching of $G_c^w[S]$ is the disjoint union of colour-$i$ perfect matchings of the connected components of $G_c^w[\mathbf{i},S]$. The weight sum therefore factorises over these components.}
\end{proof}

Consider an edge $e=(v_1,v_2)$ of colour $c(e)$. A monochromatic inherited vertex colouring of colour $c(e)$ can be inherited from perfect matchings of two types. 
\begin{enumerate}
    \item The monochromatic perfect matchings of colour $c(e)$ containing $e$.
    \item The monochromatic perfect matchings of colour $c(e)$ not containing $e$. 
\end{enumerate}
{If the sum of weights of perfect matchings of type $1$ is non-zero, we call the edge $e$ a \emph{contributing} edge. If it is $0$, we call it a non-contributing edge.}

For each pair of vertices and each colour, replace all parallel edges of that colour by a single edge whose weight is the sum of their weights. If this sum is zero, delete the entire bundle instead. This operation preserves the weight of every inherited vertex colouring: the contribution of the parallel edges factors as the sum of their weights. In particular, the weights of all feasible monochromatic colourings remain $1$, so the graph remains a GHZ graph of the same dimension. The resulting subgraph has no more than one edge of each colour between any two vertices, and neither its neighbour-degrees nor its edge-degrees have increased. We use this reduction for the multigraph bounds below. The elementary bound $\mu(G)\leq\delta_e(G)$ follows because each feasible monochromatic colour has an incident edge at every vertex. We strengthen this bound using \cref{obs:contri_edges}.
\begin{observation}
\label{obs:contri_edges}
After the parallel-edge reduction, in a GHZ graph $G_c^w$ with $|V(G)|\geq 4$, if there are two edges $e$ and $e'$ of different colours between $u,v$, then both must be non-contributing.  
\end{observation}
\begin{proof}
Towards a contradiction, let there be a contributing edge $e=(v_1,v_2)$ and another edge $e'=(v_1,v_2)$ such that $c(e')\neq c(e)$. Let $V(G)=V$ and $V'=V\setminus\{v_1,v_2\}$. Let $c(e)={i}$. Since $e$ is contributing, we know that $w(e)w(\mathbf{i}_{V'}) \neq 0$ by definition. Therefore, $w(\mathbf{i}_{V'}) \neq 0$. Let $c(e')={j}$. Consider the non-monochromatic colouring in which $\{v_1,v_2\}$ get colour $j$ and $V'$ get colour $i$. Since $e'$ is the unique colour-$j$ edge between these vertices, \cref{colour_split_lemma} gives weight $w(e')w(\mathbf{i}_{V'})\neq 0$. But a non-monochromatic colouring should have weight $0$. Contradiction. 
\end{proof}

\begin{observation}
\label{min_degree_bound}
{For a loopless multigraph $G$ with $n=|V(G)|\geq 4$, we have $\mu(G) \leq \delta_{v}(G) \leq n-1$.}
\end{observation}
\begin{proof}
{The claim is immediate when $\mu(G)=0$. Otherwise, apply the parallel-edge reduction to a colouring and weight assignment witnessing $\mu(G)$, and let the resulting GHZ graph be $H_c^w$. It has dimension $\mu(G)$ and $\delta_v(H)\leq\delta_v(G)$. Let $v$ be a vertex with exactly $\delta_v(H)$ neighbours. As each of the $\mu(G)$ monochromatic inherited vertex colourings has weight one, there must be at least one contributing edge of each of those $\mu(G)$ colours incident on $v$. If $\mu(G)>\delta_v(H)$, the pigeonhole principle gives a neighbour $u$ of $v$ with two contributing edges of different colours between $u$ and $v$, contradicting \cref{obs:contri_edges}. Therefore, $\mu(G)\leq\delta_v(H)\leq\delta_v(G)$.}
\end{proof}

\section{Maximum neighbour-degree: Proof of Theorem \ref{thm:max_degree}}
\label{sec:max_degree}
\begin{proof}
Let $d_{v}(u)$ denote the number of neighbours of a vertex $u \in G$. In $G_c^w$, let $d_{\mathbf{i}}(u)$ denote the number of edges of colour $i$ incident on $u$. Let $\Delta_{\mathbf{i}}(G_c^w) = \max\limits_{v \in V(G)}  d_{\mathbf{i}}(v)$ and $\delta_{\mathbf{i}}(G_c^w) = \min\limits_{v \in V(G)}  d_{\mathbf{i}}(v)$. We prove the following three lemmas first. 
\begin{lemma}
\label{max_deg_two}
In a GHZ graph $G_c^w$ with $|V(G)|>4$, if $\Delta_{\mathbf{i}}(G_c^w) \leq 2$, for all colours $i$, then $\mu(G,c,w)\leq 2$.
\end{lemma}
\begin{proof}
Note that if there is a counterexample $G_c^w$, by removing all of its redundant colours, we can construct a counterexample with no redundant colours. Therefore, it is sufficient to prove the statement for edge-coloured edge-weighted graphs with no redundant colours. Consider such a GHZ graph $G_c^w$.

If $G_c^w$ has no non-monochromatic perfect matchings and $|V(G)|>4$, then by the result of Bogdanov, $\mu(G,c,w)\leq 2$ \cite{Quantum_graphs}.

Therefore, let us assume that there is a non-monochromatic matching and its associated non-monochromatic inherited vertex colouring $vc$ on colours $[r]$ has weight zero. From \cref{colour_split_lemma}, there is a non-redundant colour in $[r]$, say $1$, for which $w(\mathbf{1}_{S})$ is zero, where 
$S=\{v \in V(G) \mid vc(v)=1\}$. From \cref{partition_split_lemma}, there is also a connected component $G_c^w[\mathbf{1},P]$ of $G_c^w[\mathbf{1},S]$ such that its weight, $w(\mathbf{1}_{P})=0$.

Since, $\Delta_{\mathbf{1}}(G_c^w) \leq 2$, $G_c^w[\mathbf{1},P]$ must be a cycle or path. Also, since $G_c^w[\mathbf{1},P]$ has a perfect matching in it, it must be an even cycle or a path with an odd number of edges. If it is a path with an odd number of edges, say $e_1e_2\ldots$, then  $w(\mathbf{1}_{P})=w(e_1)w(e_3)\ldots$, which cannot be zero. Therefore, it must be an even cycle.

Now consider the monochromatic inherited vertex colouring $\mathbf{1}_{V(G)}$. Note that $G_c^w[\mathbf{1},P]$ is disconnected from $G_c^w[\mathbf{1},{V(G)-P}]$ as it is a cycle and $\Delta_{\mathbf{1}}(G_c^w) \leq 2$. Therefore, from \cref{partition_split_lemma}, $w(\mathbf{1}_{V(G)})$ must be $0$, since $w(\mathbf{1}_{P})$ is zero. But $1$ is a non-redundant colour and hence its monochromatic inherited vertex colouring has weight $1$. Contradiction.
\end{proof}

\begin{lemma}
For a graph with $|V(G)|>4$, if $\Delta_{v}(G) \leq 3$, then $\mu(G) \leq 2$.
\label{maximum_degree_3}
\end{lemma}

\begin{proof}
Towards a contradiction, suppose that $\mu(G)\ge 3$.  Then there exists a
colouring $c$ and a weight function $w$ such that $\mu(G,c,w)\ge 3$.

Apply the parallel-edge reduction and delete all redundant colour classes.
These preserve the dimension and do not increase neighbour-degrees, so the
maximum remains at most $3$.  Relabelling the resulting graph as $G$, we may assume that every
colour class present is non-redundant.

If $\Delta_i(G^w_c)\le 2$ for every colour $i$, then \Cref{max_deg_two} gives
$\mu(G,c,w)\le 2$, a contradiction.  Hence there is a non-redundant colour,
say colour $1$, and a vertex $u$ such that $d_1(u)\ge 3$.

Since $\Delta_v(G)\le 3$, the vertex $u$ has exactly three neighbours, and each
of them is joined to $u$ by an edge of colour $1$.  Since colour $1$ is
non-redundant and $\mu(G,c,w)\ge 3$, there are at least two feasible colours
different from colour $1$.  For each such colour, there must be a contributing
edge of that colour incident with $u$.  Such an edge must go to one of the
three neighbours of $u$, but that neighbour is already joined to $u$ by an edge
of colour $1$.  By \Cref{obs:contri_edges}, the contributing edge would then be
non-contributing, a contradiction.
\end{proof}

\begin{lemma}
\label{max_deg_atleast_four}
{If $|V(G)|>4$ and $\Delta_v(G)\geq 4$, then
\[
    \mu(G)\leq \Delta_v(G)-2.
\]}
\end{lemma}

\begin{proof}
Let $D=\Delta_v(G)$.  Towards a contradiction, suppose that
$\mu(G)\ge D-1$.  Then there exists a colouring $c$ and a weight function $w$
such that $\mu(G,c,w)\ge D-1$.  Since $D\ge 4$, this implies
$\mu(G,c,w)\ge 3$.

Apply the parallel-edge reduction and delete all redundant colour classes.
These preserve the dimension and do not increase neighbour-degrees, so the
maximum remains at most $D$.  Relabelling the resulting graph as $G$, we may assume that every
colour class present is non-redundant.

If $\Delta_i(G^w_c)\le 2$ for every colour $i$, then \Cref{max_deg_two} gives
$\mu(G,c,w)\le 2$, a contradiction.  Hence there is a non-redundant colour,
say colour $1$, and a vertex $u$ such that $d_1(u)\ge 3$.

Since colour $1$ is feasible and $\mu(G,c,w)\ge D-1$, there are at least
$D-2$ feasible colours different from colour $1$.  For each such colour, choose
one contributing edge of that colour incident with $u$.  By \Cref{obs:contri_edges},
none of these contributing edges can go to a neighbour of $u$ that is already
joined to $u$ by an edge of colour $1$.  Also by \Cref{obs:contri_edges}, two such
contributing edges of different colours cannot go to the same neighbour.

Therefore $u$ has at least
\[
d_1(u)+(D-2) \ge 3+(D-2)=D+1
\]
distinct neighbours, contradicting their upper bound $D$.
Thus the original graph has matching index at most $D-2$.
\end{proof}


{Since $\Delta_v(G) \leq |V(G)|-1$, Lemmas~\ref{maximum_degree_3} and~\ref{max_deg_atleast_four} imply Theorem~\ref{thm:max_degree}.}
\end{proof}

\section{Edge connectivity: Proof of Theorem \ref{thm:edge_connectivity}}
\label{sec:edge_connectivity}
\begin{proof}
Towards a contradiction, suppose that there is a loopless connected multigraph $G''$
such that
\[
    \mu(G'')\ge \lambda(G'')+1.
\]
Choose a colouring $c$ and a weight function $w$ witnessing this dimension.
Delete all redundant edges and then all redundant colour classes. The dimension
is unchanged. Let the resulting graph be $G$. Then
\[
    \mu(G,c,w)=\mu(G'')\ge \lambda(G'')+1.
\]
Moreover, $G$ is a subgraph of $G''$. Suppose that $G$ were disconnected,
with component vertex sets $C_1,\ldots,C_s$, where $s\geq 2$.
For each feasible monochromatic colour $i$, \Cref{partition_split_lemma},
with its factors grouped by components of $G$, gives
$1=w(\mathbf{i}_{V(G)})=\prod_{t=1}^{s}w(\mathbf{i}_{C_t})$.
If two such colours $i,j$ existed, assigning colour $i$ to $C_1$ and colour
$j$ to all other components would, by \Cref{colour_split_lemma} and the
same component factorisation, give the non-zero weight
$w(\mathbf{i}_{C_1})\prod_{t=2}^{s}w(\mathbf{j}_{C_t})$.
This contradicts the GHZ condition. Thus a disconnected $G$ would satisfy
$\mu(G,c,w)\leq 1$, contradicting $\lambda(G'')\geq 1$ and
$\mu(G,c,w)\geq\lambda(G'')+1$. Hence $G$ is connected.
In particular,
\[
    \lambda(G)\le \lambda(G'').
\]

Let $(S,S')$ be a minimum edge cut of $G$, so $S'=V(G)\setminus S$ and
$|(S,S')|=\lambda(G)$. Since $G$ has a perfect matching, $|V(G)|$ is even,
and therefore $|S|$ and $|S'|$ have the same parity.

First suppose that $|S|$ and $|S'|$ are odd.  Every monochromatic perfect
matching must contain at least one edge of the cut $(S,S')$.  Therefore every
feasible monochromatic colour appears on at least one edge of the cut. Hence
\[
\mu(G,c,w)\le |(S,S')|=\lambda(G)\le \lambda(G''),
\]
contradicting $\mu(G,c,w)\ge \lambda(G'')+1$.

Now suppose that $|S|$ and $|S'|$ are even.  Let $A$ be the set of feasible
colours for which no monochromatic perfect matching crosses the cut
$(S,S')$, and put $r=|A|$.  Let $B$ be the remaining feasible colours and put
$r'=|B|$.  Thus
\[
\mu(G,c,w)=r+r'.
\]

For every colour $i\in B$, some colour-$i$ monochromatic perfect matching
crosses the cut.  Since both sides of the cut have even cardinality, such a
matching uses at least two cut edges of colour $i$.  Therefore
\[
\lambda(G)=|(S,S')|\ge 2r'.
\]

We claim that $r\le 1$.  Suppose not, and choose two colours $1,2\in A$.
Since no colour-$i$ monochromatic perfect matching crosses the cut for
$i=1,2$, all such matchings split between the two sides of the cut.  Hence
\[
w(1_{V(G)})=w(1_S)w(1_{S'})=1
\quad\text{and}\quad
w(2_{V(G)})=w(2_S)w(2_{S'})=1.
\]
In particular, $w(1_S)$ and $w(2_{S'})$ are non-zero.

Consider the inherited vertex colouring $vc$ in which every vertex of $S$ gets
colour $1$ and every vertex of $S'$ gets colour $2$.  Any perfect matching
inducing $vc$ contains no cut edge: a cut edge in an ordinary edge-colouring
would give the same colour to its two endpoints.  Therefore, by
\Cref{colour_split_lemma},
\[
w(vc)=w(1_S)w(2_{S'})\ne 0.
\]
This is impossible because $vc$ is non-monochromatic.  Hence $r\le 1$.

If $r'\ge 1$, then
\[
\mu(G,c,w)=r+r'\le 1+r'\le 2r'\le \lambda(G)\le \lambda(G''),
\]
again contradicting $\mu(G,c,w)\ge \lambda(G'')+1$.  If $r'=0$, then
$\mu(G,c,w)=r\le 1$, also a contradiction.  Therefore no such $G''$ exists.
\end{proof}


\section{Vertex connectivity for simple graphs: Proof of Theorem \ref{thm:vertex_connectivity}}
\label{sec:vertex_connectivity}
\begin{proof}
If $G$ is a complete graph, from \cref{min_degree_bound}, $\mu(G) \leq |V(G)|-1$. As $\kappa(G)=|V(G)|-1$, it is easy to see that the given statement holds. We now consider simple connected graphs not isomorphic to complete graphs.
\begin{lemma}
\label{vertex_conn_strong_version}
If $T$ is a minimum vertex separator of $G$, then
\[
    \mu(G) \leq 2^{|T|-1}+|E(T)|.
\]
\end{lemma}
\begin{proof}
Let $k=|T|=\kappa(G)$. Let a connected component of $G[V(G)-T]$ be $G[S]$, and let $S'=V(G)-T-S$. Towards a contradiction, assume that
\[
    \mu(G) \geq 2^{k-1}+|E(T)|+1.
\]
Therefore, there exists a colouring $c$ and a weight function $w$ such that
\[
    \mu(G)=\mu(G,c,w) \geq 2^{k-1}+|E(T)|+1.
\]
Since there are $|E(T)|$ edges with both endpoints in $T$, there can be at most $|E(T)|$ colour classes containing an edge in $T$. Therefore, there are at least $2^{k-1}+1$ non-redundant colour classes that do not contain any edge from $G_c^w[T]$. Let those non-redundant colour classes be $\{1,2,\ldots,2^{k-1}+1\}$.

For each $i\in [2^{k-1}+1]$, let $M^i_{V(G)}\ne\emptyset$ be the set of
colour-$i$ monochromatic perfect matchings of $G^w_c$.

For $J\subseteq T$, write $J^c=T\setminus J$, and define
\[
a_i(J)=w(i_{S\cup J})
\quad\text{and}\quad
b_i(J)=w(i_{S'\cup J^c}).
\]
Let $
\mathcal{T}=\{J\subseteq T:\ |S\cup J|\text{ is even}\}.$
Then $|\mathcal{T}|=2^{k-1}$.

Since the colours under consideration have no edge inside $T$, every
colour-$i$ monochromatic perfect matching of $G$ splits uniquely as a
colour-$i$ perfect matching of $G[S\cup J]$ together with a colour-$i$ perfect
matching of $G[S'\cup J^c]$, for a unique $J\in\mathcal{T}$.  Therefore
\[
\sum_{J\in\mathcal{T}} a_i(J)b_i(J)
=
w(i_{V(G)})
=
1.
\]
Hence, for each such colour $i$, there exists $J_i\in\mathcal{T}$ such that
$
a_i(J_i)b_i(J_i)\ne 0.
$
Since there are $2^{k-1}+1$ colours and only
$2^{k-1}$ choices for $J_i$, two colours, say $1$ and $2$, satisfy
$J_1=J_2=J$.

Thus
\[
a_1(J)b_1(J)\ne 0
\quad\text{and}\quad
a_2(J)b_2(J)\ne 0,
\]
so in particular
\[
a_1(J)b_2(J)\ne 0.
\]
Consider the inherited vertex colouring in which $S\cup J$ is coloured $1$ and
$S'\cup J^c$ is coloured $2$.  By \Cref{colour_split_lemma}, its weight is
\[
a_1(J)b_2(J)\ne 0,
\]
contradicting the GHZ condition because this inherited vertex colouring is
non-monochromatic.
\end{proof}
Since $T$ is a minimum vertex separator, $|T|=\kappa(G)$, and since $G$ is simple we have $|E(T)|\leq \binom{\kappa(G)}{2}$. Hence \cref{thm:vertex_connectivity} follows.
\end{proof}

\section{Graphs with six or eight vertices: Proof of Theorem \ref{thm:six_eight_vertices}}
\label{sec:six_vertices}
\subsection{Six-vertex case}
\begin{proof}
Towards a contradiction, let $\mu(G) \geq 3$. Therefore, there exists a  colouring $c$ and weight function $w$, such that $\mu(G,c,w)\geq 3$. Let three of its non-redundant colours be $1$, $2$ and $3$. Consider the union of a colour $1$ perfect matching and a colour $2$ perfect matching. Their union is a disjoint union of even cycles whose edges alternate between colours $1,2$. Since $G$ is simple and the two matchings are edge-disjoint, every such cycle has length at least $4$. With only $6$ vertices, their union must therefore be a single $6$-cycle. Let the vertices of such a $6$ cycle be labelled $abcdef$ in clockwise direction. Without loss of generality, let $c(ab)=c(cd)=c(ef)=1$ and $c(bc)=c(de)=c(fa)=2$.

{We call $(a,d)$, $(b,e)$, and $(c,f)$ the antipodal pairs.} We claim that any perfect matching $M$ formed by non-cyclic edges must have at least one edge containing an antipodal pair. Suppose not. Observe that any edge connecting a vertex from $\{a,c,e\}$ to $\{b,d,f\}$ is either a cyclic edge or contains an antipodal pair. {Thus $M$ would have to match the vertices of $\{a,c,e\}$ among themselves and the vertices of $\{b,d,f\}$ among themselves, which is impossible because both sets have odd cardinality.}

Therefore, for the monochromatic matching of colour $3$, there is an edge containing an antipodal pair, say $ad$, without loss of generality. Consider the non-monochromatic inherited vertex colouring in which $a,d$ are coloured $3$, $b,c$ are coloured $2$ and $e,f$ are coloured $1$. By \cref{colour_split_lemma}, the weight of such a vertex colouring is $w(ad)w(bc)w(ef)$. Since the vertex colouring is non-monochromatic, $w(vc) = 0$. Therefore, one of these three edges must have weight zero. Contradiction.
\end{proof} 

\subsection{Eight-vertex case for Theorem~\ref{thm:six_eight_vertices}}
\label{sec:eight_vertices}
For the eight vertex case, the proof has two main cases. In Case~1, every pair of monochromatic perfect matchings forms two disjoint $4$-cycles; we show that a third colour then forces an alternating Hamiltonian cycle, contradicting the case assumption. In Case~2, we fix an alternating red-green Hamiltonian cycle and classify the remaining colours according to whether one of their matching edges separates the cycle into two even parts. Figures~\ref{fig:eightv_c3}--\ref{fig:eightv_c4} list the resulting configurations up to dihedral symmetry and interchange of colour names.

